/**
 * The track's tempo from Spotify, if it gave one, and the palette, settings and lights the show plays it with. `base` is
 * the colour the palette was built from, so a new palette type keeps it.
 */
case class TrackShow(tempo: Option[Double], palette: Palette, settings: LightShowConfig, zone: Zone, base: RGB) {
  def bpm: Double = tempo.getOrElse(settings.defaultBpm) / settings.beatsPerPulse
}

class SyncEngine[F[_]: Async] private (
  config: AppConfig,
  live: LiveSettings[F],
  zone: Zone,
  spotify: SpotifyClient[F],
  lights: Lights[F],
  current: Ref[F, Option[(TrackId, TrackShow)]],
  random: Random,
  audio: Stream[F, AudioReading],
  covers: AlbumCovers[F]
):

  private val logger: SelfAwareStructuredLogger[F] = Slf4jLogger.getLogger[F]

  private def randomBase: F[RGB] = ???

  private def paletteFrom(base: RGB, paletteType: PaletteType): F[Palette] = ???

  /**
   * The base colour from the song's album cover, if the settings take it from there and it's read within
   * `SyncEngine.CoverWait`. None otherwise, logging one warning if the cover couldn't be fetched or read in time.
   */
  private def coverBase(trackId: TrackId, cover: Option[String], settings: LightShowConfig): F[Option[RGB]] = ???

  /** The lights to play `settings` on: the area they name, or else the ones `before` played on (or the first zone). */
  private def zoneFor(settings: LightShowConfig, before: Option[TrackShow]): F[Zone] = {
    val fallback = before.fold(zone)(_.zone)
    settings.area match {
      case None => Async[F].pure(fallback)
      case Some(name) if before.exists(_.settings.area.contains(name)) => Async[F].pure(fallback)
      case Some(name) =>
        lights.zone(name).attempt.flatMap {
          case Right(Some(found)) => logger.info(s"Playing on the $name area").as(found)
          case Right(None) => logger.warn(s"There's no $name area on the bridge; staying where the show is").as(fallback)
          case Left(err) => logger.warn(s"Couldn't read the $name area from the bridge, staying where the show is: $err").as(fallback)
        }
    }
  }

  /**
   * The show for a track. A new track takes up the latest settings, its area's lights and a new palette, built from its
   * album cover's colour when there is one; the show then stays the same until the track changes, so changes from the
   * settings page wait for the next song.
   */
  def showFor(trackId: TrackId, cover: Option[String] = None): F[TrackShow] = ???

  /** The palette of the song playing now, if one has started. */
  def palette: F[Option[Palette]] = current.get.map(_.map(_._2.palette))

  /**
   * Takes up the latest settings now rather than at the next song, moving to another area if they name one. The palette
   * only changes if its type did, and is then built from the song's base colour.
   */
  def applyNow: F[Unit] = ???

  /**
   * Keeps `audioRef` up to date with what the music is doing, logging when the beat locks on, is lost or changes
   * tempo. On failure it clears the reading, so the show carries on with Spotify timing and no audio effects.
   */
  private def followAudio(audioRef: Ref[F, Option[AudioReading]]): Stream[F, Nothing] =
    audio
      .evalMapAccumulate(Option.empty[Double]) { (logged, reading) =>
        val (remembered, news) = SyncEngine.beatNews(logged, reading.beat)
        (news.traverse_(logger.info(_)) *> audioRef.set(Some(reading))).as((remembered, ()))
      }
      .drain
      .handleErrorWith { err =>
        Stream.exec(audioRef.set(None) *> logger.warn(s"Listening stopped, using Spotify timing instead: ${err.getMessage}"))
      }

  def run: Stream[F, Frame] =
    Stream.eval((SignallingRef[F, Option[LocalPlayback]](None), Ref.of[F, Option[AudioReading]](None)).tupled).flatMap { (stateRef, audioRef) =>
      val poller = Stream.awakeEvery[F](config.pollingIntervalMs.millis)
        .evalMap { _ =>
          spotify.getPlaybackState.handleErrorWith { err =>
            logger.error(s"Spotify Poll Failed: $err") *> Async[F].pure(None)
          }
        }
        .evalMap(state => Clock[F].realTimeInstant.map(now => state.map(LocalPlayback(_, now))))
        .evalMap(stateRef.set)

      val renderer = Stream.awakeEvery[F](config.lightShow.frameIntervalMs.millis)
        .evalMap(_ => stateRef.get)
        .evalMapAccumulate(Renderer.initial) { (rendered, playback) =>
          playback.filter(_.state.isPlaying) match {
            case Some(local) => playingFrame(local, audioRef).map(Renderer.playing)
            case None =>
              (Clock[F].monotonic, live.applied, current.get).mapN { (now, show, playing) =>
                Renderer.paused(rendered, now, playing.fold(zone)(_._2.zone), show.pause)
              }
          }
        }
        .map(_._2)

      renderer.merge(poller.drain).merge(followAudio(audioRef))
        .zipWithIndex
        .map((frame, i) => frame.copy(sequence = (i % 256).toInt))
    }

  /**
   * The frame for the current moment of a playing track. With a live beat, pulses follow it; otherwise they follow
   * Spotify's playback position at the track's tempo. With live audio, the effects follow the music too.
   */
  private def playingFrame(local: LocalPlayback, audioRef: Ref[F, Option[AudioReading]]): F[Frame] =
    for {
      track <- showFor(local.state.trackId, local.state.albumCoverUrl)
      show = track.settings
      reading <- audioRef.get
      monotonic <- Clock[F].monotonic
      now <- Clock[F].realTimeInstant
      heardAt = monotonic + show.audio.offsetMs.millis
      pulses = reading.flatMap(_.beat) match {
        case Some(b) => b.beatsAt(heardAt) / show.beatsPerPulse
        case None =>
          val latencyMs = java.time.Duration.between(local.receivedAt, now).toMillis
          SyncEngine.pulsesAt(local.state.progress.toMillis + latencyMs + show.syncOffsetMs, track.bpm)
      }
      effects = reading
        .filter(_ => show.reactive.enabled)
        .fold(Effects.neutral)(r => Effects.at(heardAt, r, track.zone.channels.size, show.reactive))
    } yield SyncEngine.pulseFrame(track.zone, track.palette, pulses, show.pulse, effects)

object SyncEngine:

  /** `covers` reads album covers' colours; without it, every song gets a random palette. */
  def make[F[_]: Async](
    config: AppConfig,
    live: LiveSettings[F],
    spotify: SpotifyClient[F],
    zone: Zone,
    lights: Lights[F],
    random: Random = new Random(),
    audio: Stream[F, AudioReading] = Stream.empty,
    covers: Option[AlbumCovers[F]] = None
  ): F[SyncEngine[F]] =
    Ref.of[F, Option[(TrackId, TrackShow)]](None).map(
      new SyncEngine[F](config, live, zone, spotify, lights, _, random, audio, covers.getOrElse(AlbumCovers.none[F]))
    )

  /** How long a song's start waits for its album cover before playing a random palette. */
  val CoverWait: FiniteDuration = 1.second

  /** How far the tempo has to move from the last one logged before it's logged again. */
  private val TempoChangeToLog: Double = 0.03

  /**
   * What to log about the beat, given the tempo logged last and the latest beat: that it locked on, that it was lost,
   * or that the tempo moved by more than `TempoChangeToLog`. Returns the tempo to remember and the message, if any.
   */
  def beatNews(logged: Option[Double], beat: Option[BeatState]): (Option[Double], Option[String]) =
    (logged, beat) match {
      case (None, Some(b)) => (Some(b.bpm), Some(f"Locked onto the beat at ${b.bpm}%.1f BPM (confidence ${b.confidence}%.1f)"))
      case (Some(_), None) => (None, Some("Lost the beat; using Spotify timing until it's back"))
      case (Some(was), Some(b)) if math.abs(b.bpm - was) / was > TempoChangeToLog =>
        (Some(b.bpm), Some(f"Tempo changed from $was%.1f to ${b.bpm}%.1f BPM (confidence ${b.confidence}%.1f)"))
      case _ => (logged, None)
    }

  /** Pulses elapsed at a playback position, pulsing at `bpm`. */
  def pulsesAt(positionMs: Long, bpm: Double): Double = positionMs * bpm / 60000.0

  private val White: RGB = RGB.safe(255, 255, 255).get

  /**
   * One frame of the show for every channel in the zone, `pulses` pulses into the music. Light i takes palette colour
   * i, and what it does depends on its role:
   *  - a pulse light peaks `stagger` of a pulse after light i - 1 (light 0 on every whole pulse), so the pulse travels
   *    across the zone, and its hue turns with the treble;
   *  - a rhythm light pulses with the bar's kick pattern, or on every pulse until there's a live beat;
   *  - a colour light swells once every `swell.beats` beats, peaking on the beat, and moves along the palette as the
   *    music goes higher or lower.
   * The effects scale the brightness and push lights towards white for flashes and sparkles.
   */
  def pulseFrame(zone: Zone, palette: Palette, pulses: Double, settings: PulseSettings, effects: Effects = Effects.neutral): Frame = {
    val updates = zone.channels.zipWithIndex.map { (channel, i) =>
      val (brightness, colour) = effects.roleOf(i) match {
        case LightRole.Pulse =>
          val own = palette.getColor(i)
          val level = Pulse.onBeat(pulses - i * settings.stagger, settings)
          (Pulse.brightness(level, settings, effects.intensity), if (effects.hueShift == 0) own else own.rotateHue(effects.hueShift))
        case LightRole.Rhythm =>
          val level = effects.rhythm.fold(Pulse.onBeat(pulses, settings))(r => Pulse.rhythm(r.groove, r.beats, settings))
          (Pulse.brightness(level, settings, effects.intensity), palette.getColor(i))
        case LightRole.Colour =>
          // Counted along the beat grid when there's a live beat, so every other beat stays the same beat as the tracker re-estimates.
          val beats = effects.rhythm.fold(pulses)(_.beats)
          val shape = effects.swell.shape
          (Pulse.brightness(Pulse.onBeat(beats / effects.swell.beats, shape), shape, effects.intensity), palette.along(i, effects.paletteShift))
      }
      val lit = colour.scaleBrightness(brightness)
      val white = effects.whiteFor(i)
      LightUpdate(channel, if (white <= 0) lit else lit.mix(White, white))
    }
    Frame(zone.id, updates)
  }

import cats.effect.*
import cats.effect.{ExitCode, IOApp}
import cats.effect.kernel.Resource
import cats.effect.std.Env
import client.{AlbumCovers, DtlsEmitter, EntertainmentStream, HttpClients, HueClient, SpotifyClient, TokenFile, TokenStore}
import cats.syntax.all.*
import beat.{BeatTracking, TrackerSettings}
import domain.config.{AppConfig, BeatSource}
import domain.hue.{MusicArea, Zone}
import domain.engine.RGB
import settings.{LiveSettings, SettingsRoutes, SettingsServer, ShowControls}
import org.typelevel.log4cats.slf4j.Slf4jLogger
import pureconfig.ConfigSource
import pureconfig.error.ConfigReaderException
object Main extends IOApp {
  private val logger = Slf4jLogger.getLogger[IO]

  private def controls(engine: SyncEngine[IO], lights: Lights[IO]): ShowControls[IO] =
    new ShowControls[IO] {
      def applyNow: IO[Unit] = engine.applyNow
      def areas: IO[List[MusicArea]] = lights.areas
      def palette: IO[Vector[RGB]] = engine.palette.map(_.fold(Vector.empty)(_.colors))
    }

  override def run(args: List[String]): IO[ExitCode] = start(ConfigSource.default)

  def start(source: ConfigSource): IO[ExitCode] = {
    val resources = for {
      config <- Resource.eval(AppConfig.load[IO](source))
      clients <- HttpClients.resource[IO]

      env <- Resource.eval(Env[IO].entries.map(_.toMap))
      store <- Resource.eval(TokenStore.at[IO](TokenFile.locate(config.spotify.tokenFile, env)))
      spotify <- SpotifyClient.resource[IO](clients.spotify, config.spotify, store)
      hueClient = new HueClient[IO](config.hue.creds, clients.bridge)
      emitter = new DtlsEmitter[IO](config.hue.creds)

      lights <- Resource.eval(Lights.fromBridge[IO](hueClient))
      areas <- Resource.eval(lights.areas)
      area <- Resource.eval(MusicArea.choose(areas, config.lightShow.area, config.hue.zoneId).leftMap(new IllegalArgumentException(_)).liftTo[IO])
      _ <- Resource.eval(logger.info(
          s"Entertainment areas on the bridge: ${areas.map(a => s"${a.name} (${a.lights} lights)").mkString(", ")}. Playing on ${area.name}."
        ))
      live <- Resource.eval(LiveSettings.make[IO](config.lightShow.copy(area = Some(area.name)), areas))
      channels <- Resource.eval(hueClient.getChannels(area.id))
      audio = config.lightShow.beatSource match {
        case BeatSource.Audio => BeatTracking.listen[IO](config.lightShow.audio.device, live.applied.map(TrackerSettings.from))
        case BeatSource.Spotify => fs2.Stream.empty
      }
      _ <- Resource.eval(logger.info(
          s"Listening for the beat on '${config.lightShow.audio.device}'. If it never locks on, check that music is playing through it and that your terminal has microphone access."
        ).whenA(config.lightShow.beatSource == BeatSource.Audio))
      covers <- Resource.eval(AlbumCovers.fromHttp[IO](clients.spotify))
      engine <- Resource.eval(SyncEngine.make[IO](config, live, spotify, Zone(area.id, channels), lights, audio = audio, covers = Some(covers)))
      _ <-
        if (!config.ui.enabled) Resource.unit[IO]
        else
          SettingsServer.resource[IO](config.ui, SettingsRoutes[IO](live, controls(engine, lights)))
            .evalMap(server => logger.info(s"Settings page at ${server.baseUri}; changes take effect when the next song starts"))
    } yield (hueClient, emitter, engine)

    resources.use { (hueClient, emitter, engine) =>
      engine.run.through(EntertainmentStream.toBridge(hueClient, emitter)).compile.drain.as(ExitCode.Success)
    }.recoverWith { case e: ConfigReaderException[?] =>
      logger.error(e.failures.prettyPrint()).as(ExitCode.Error)
    }
  }
}

package ui

/** Settings in a section that aren't sliders, each with its own control, shown before the section's sliders. */
enum Control derives CanEqual {
  case Area, Roles, Reactions, Palette, AlbumCoverColours, SongPalette, RestingColour, FixedSettings

  /** The settings this control shows, by their path in the config file. */
  def keys: List[String] = this match {
    case Area => List("area")
    case Roles => List("reactive.roles")
    case Reactions => List("reactive.enabled")
    case Palette => List("palette")
    case AlbumCoverColours => List("album-cover-colours")
    case SongPalette => Nil
    case RestingColour => List("pause.resting-colour")
    case FixedSettings => List("beat-source", "audio.device", "frame-interval-ms")
  }
}

package ui

import com.raquo.laminar.api.L.*
import domain.config.{ConfigSnippet, LightShowConfig, SettingsView}
import domain.engine.{LightRole, PaletteType, RGB}
import domain.hue.MusicArea

/**
 * The settings page. Edits are saved a moment after the last change, as the settings for the next song; the page
 * shows which are still waiting, and can take them up now, reset them to the config file, or copy them as config.
 */
final class SettingsPage {

  private val server = Var(Option.empty[SettingsView])
  private val draft = Var(Option.empty[LightShowConfig])
  private val serverProblems = Var(List.empty[String])
  private val areas = Var(List.empty[MusicArea])
  private val songPalette = Var(List.empty[RGB])

  private def edit(change: LightShowConfig => LightShowConfig): Unit = draft.update(_.map(change))

  private val localProblems: Signal[List[String]] = draft.signal.map(_.fold(Nil)(LightShowConfig.problems))

  /** Settings whose new value is waiting for the next song, by their path in the config file. */
  private val waiting: Signal[Set[String]] =
    server.signal.combineWith(draft.signal).map {
      case (Some(view), Some(edited)) => ConfigSnippet.changes(view.applied, edited).map(_._1).toSet
      case _ => Set.empty
    }

  private def received(answer: Either[List[String], SettingsView]): Unit =
    answer.fold(found => serverProblems.set(found), { view => server.set(Some(view)); serverProblems.set(Nil) })

  private def loaded(answer: Either[List[String], SettingsView]): Unit = {
    received(answer)
    answer.foreach(view => draft.set(Some(view.pending)))
  }

  def view: HtmlElement =
    div(
      cls := "page",
      Api.settings --> (answer => loaded(answer)),
      Api.areas --> {
        case Right(found) => areas.set(found)
        case Left(failed) => serverProblems.set(failed)
      },
      EventStream.periodic(2000).drop(1).flatMapSwitch(_ => Api.settings) --> (answer => received(answer)),
      EventStream.periodic(2000).flatMapSwitch(_ => Api.palette) --> (answer => answer.foreach(songPalette.set)),
      draft.signal.changes.debounce(300).collect { case Some(edited) if LightShowConfig.problems(edited).isEmpty => edited }
        .flatMapSwitch(Api.save) --> (answer => received(answer)),
      headerTag(
        h1("Light show settings"),
        p("Changes take effect when the next song starts and last until the app stops. Your config file isn't changed."),
        div(
          cls := "actions",
          button("Apply now", onClick.flatMapStream(_ => Api.applyNow) --> (answer => received(answer))),
          button("Reset to config file", onClick.flatMapStream(_ => Api.reset) --> (answer => loaded(answer)))
        ),
        p(
          cls := "status",
          child.text <-- waiting.map(paths =>
            if (paths.isEmpty) "The lights are playing these settings."
            else s"${paths.size} ${if (paths.size == 1) "change waits" else "changes wait"} for the next song."
          )
        ),
        ul(cls := "problems", children <-- localProblems.combineWith(serverProblems.signal).map((a, b) => (a ++ b).distinct.map(li(_))))
      ),
      child <-- draft.signal.map(_.isDefined).distinct.map { ready =>
        if (!ready) p("Loading the settings…")
        else div(cls := "sections", Sections.all.map(section), snippet)
      }
    )

  private def marked(key: String): Modifier[HtmlElement] = cls("waiting") <-- waiting.map(_.contains(key))

  private def section(s: Section): HtmlElement = {
    val unused = draft.signal.map(_.flatMap(s.unused))
    div(
      cls := "section",
      cls("unused") <-- unused.map(_.isDefined),
      h2(s.title),
      p(cls := "intro", s.intro),
      child.maybe <-- unused.map(_.map(reason => p(cls := "unused-note", reason))),
      s.controls.map(control),
      s.sliders.map(slider)
    )
  }

  private def slider(s: Slider): HtmlElement = {
    val current = draft.signal.map(_.fold(s.min)(s.get))
    val decimals = if (s.step >= 1) 0 else if (s.step >= 0.1) 1 else 2
    div(
      cls := "field",
      marked(s.key),
      label(span(s.label), span(cls := "value", child.text <-- current.map(v => s"%.${decimals}f".format(v)))),
      input(
        typ := "range",
        minAttr := s.min.toString,
        maxAttr := s.max.toString,
        stepAttr := s.step.toString,
        controlled(value <-- current.map(_.toString), onInput.mapToValue --> (v => v.toDoubleOption.foreach(d => edit(c => s.set(c, d)))))
      ),
      p(cls := "help", s.help)
    )
  }

  private def control(c: Control): HtmlElement = c match {
    case Control.Area => areaChoice
    case Control.Roles => roles
    case Control.Reactions => reactionsSwitch
    case Control.Palette => paletteChoice
    case Control.AlbumCoverColours => albumCoverSwitch
    case Control.SongPalette => songColours
    case Control.RestingColour => restingColour
    case Control.FixedSettings => fixedSettings
  }

  private val rolesNow: Signal[List[LightRole]] = draft.signal.map(_.fold(Nil)(_.reactive.roles))

  private def setRoles(change: List[LightRole] => List[LightRole]): Unit =
    edit(c => c.copy(reactive = c.reactive.copy(roles = change(c.reactive.roles))))

  private def roles: HtmlElement =
    div(
